"""Experiment-framework adapter for v2 heterogeneous theory frontiers."""
from typing import Any,Mapping
from studies.risk_granularity import evaluate_configuration
def run(config:Mapping[str,Any]):
 r=evaluate_configuration(config['dataset_generation_parameters'],int(config['seed']),config['hyperparameters']['thresholds'],config['hyperparameters']['epsilons'])
 return {'metrics':{'accuracy':r['accuracy'],'macro_f1':r['macro_f1'],'auroc':None,'calibration_error':None,'additional':{'nll':r['nll'],'brier':r['brier'],'global_frontier':r['global_frontier'],'oracle_frontier':r['oracle_frontier'],'risk_budget_points':r['risk_budget_points'],'global_positive_regret_fraction':r['global_positive_regret_fraction'],'global_mean_regret':r['global_mean_regret'],'inner_runtime_seconds':r['runtime_seconds_inner'],'memory_bytes_estimate':r['memory_bytes_estimate'],'region_types':r['meta']['region_types']}},'structure':{'granule_count':r['granules'],'average_granule_size':None,'uncertain_sample_ratio':None,'additional':{'compression_ratio':r['compression_ratio'],'max_granules':r['max_granules']}},'outcome':'success','notes':'V2 independent heterogeneous-region frontier; known region routing is an existence-proof limitation.'}
